package com.lianxibu.site.controller.sources;
import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.lianxibu.site.service.identity.IdentityService;import com.lianxibu.site.service.identity.IdentityService.Actor;import com.lianxibu.site.service.sources.OwnerSourceReadService;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.ObjectProvider;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import java.util.*;
class OwnerSourceControllerTest {
 private IdentityService auth;private OwnerSourceReadService service;private MockMvc mvc;private ObjectProvider<OwnerSourceReadService> provider;private static final Actor OWNER=new Actor("fictional-owner","owner");
 @BeforeEach @SuppressWarnings("unchecked") void setup(){auth=mock(IdentityService.class);service=mock(OwnerSourceReadService.class);ObjectProvider<IdentityService> identities=mock(ObjectProvider.class);provider=mock(ObjectProvider.class);when(identities.getIfAvailable()).thenReturn(auth);when(provider.getIfAvailable()).thenReturn(service);when(auth.authenticate("fictional-session")).thenReturn(OWNER);mvc=MockMvcBuilders.standaloneSetup(new OwnerSourceController(identities,provider)).build();}
 private Map<String,Object> data(){var v=new LinkedHashMap<String,Object>();v.put("id","fictional-source");v.put("name","Fictional");v.put("category","news_tech");v.put("revision",0L);v.put("config_revision",0L);v.put("activation_stage","disabled");v.put("draft_config",null);v.put("effective_config",null);v.put("config_valid_until",null);return v;}
 @Test void exactClosedCurrentSourceReturnsNoStoreAndKnownZero()throws Exception{when(service.read(OWNER,"fictional-source")).thenReturn(data());mvc.perform(get("/admin/sources/fictional-source").cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session"))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.revision").value(0)).andExpect(jsonPath("$.data.config_revision").value(0)).andExpect(jsonPath("$.data.draft_config").value(org.hamcrest.Matchers.nullValue())).andExpect(jsonPath("$.data.config_json").doesNotExist()).andExpect(jsonPath("$.meta.request_id").isString());verify(service).read(OWNER,"fictional-source");}
 @Test void authenticationAndQueryValidationPrecedeStorage()throws Exception{mvc.perform(get("/admin/sources/fictional-source")).andExpect(status().isUnauthorized());when(auth.authenticate("fictional-session")).thenReturn(new Actor("fictional-user","user"));mvc.perform(get("/admin/sources/fictional-source").cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session"))).andExpect(status().isForbidden());when(auth.authenticate("fictional-session")).thenReturn(OWNER);for(String q:List.of("?page=1","?source_id=x&source_id=y"))mvc.perform(get("/admin/sources/fictional-source"+q).cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session"))).andExpect(status().isBadRequest());mvc.perform(get("/admin/sources/"+"x".repeat(81)).cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session"))).andExpect(status().isUnprocessableEntity());verifyNoInteractions(service);}
 @Test void missingMappingAndUnavailableRetainExactSafeErrorSemantics()throws Exception{when(service.read(OWNER,"fictional-source")).thenThrow(new OwnerSourceReadService.Missing()).thenThrow(new OwnerSourceReadService.MappingRequired()).thenThrow(new OwnerSourceReadService.Unavailable());for(int code:List.of(404,503,503)){var result=mvc.perform(get("/admin/sources/fictional-source").cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session"))).andExpect(status().is(code)).andExpect(header().string("Cache-Control","no-store"));if(code==503)result.andExpect(header().string("Retry-After","1"));}when(provider.getIfAvailable()).thenReturn(null);mvc.perform(get("/admin/sources/fictional-source").cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session"))).andExpect(status().isServiceUnavailable());}
 @Test void wrongIdentityOrExtraInternalFieldsCannotBeSerialized()throws Exception{var v=data();v.put("config_json","fictional forbidden");when(service.read(OWNER,"fictional-source")).thenReturn(v);mvc.perform(get("/admin/sources/fictional-source").cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session"))).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.data").doesNotExist());v=data();v.put("id","fictional-other");when(service.read(OWNER,"fictional-source")).thenReturn(v);mvc.perform(get("/admin/sources/fictional-source").cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session"))).andExpect(status().isServiceUnavailable());}
}
